<script setup lang="ts">
import { ref, computed, onMounted, onUnmounted } from 'vue'
import { useAuthStore } from '@stores/useAuthStore'
import { useVoiceStore } from '@stores/useVoiceStore'
import { useHead } from '@vueuse/head'

const authStore = useAuthStore()
const voiceStore = useVoiceStore()

useHead({
  title: 'Einstellungen - SimpleVoiceChat',
})

const settings = computed(() => voiceStore.settings)
const inputDevices = computed(() => voiceStore.availableInputDevices)
const outputDevices = computed(() => voiceStore.availableOutputDevices)

const testTonePlaying = ref(false)
let testAudioContext: AudioContext | null = null
let testOscillator: OscillatorNode | null = null

async function refreshDevices() {
  await voiceStore.requestDevicePermissions()
  voiceStore.updateInputDevices()
  voiceStore.updateOutputDevices()
}

async function playTestTone() {
  if (testTonePlaying.value) {
    stopTestTone()
    return
  }
  
  try {
    testAudioContext = new AudioContext()
    testOscillator = testAudioContext.createOscillator()
    const gainNode = testAudioContext.createGain()
    
    testOscillator.type = 'sine'
    testOscillator.frequency.value = 440
    gainNode.gain.value = 0.1
    
    testOscillator.connect(gainNode)
    gainNode.connect(testAudioContext.destination)
    
    testOscillator.start()
    testTonePlaying.value = true
  } catch (err) {
    console.error('Test tone error:', err)
  }
}

function stopTestTone() {
  if (testOscillator) {
    testOscillator.stop()
    testOscillator.disconnect()
    testOscillator = null
  }
  if (testAudioContext) {
    testAudioContext.close()
    testAudioContext = null
  }
  testTonePlaying.value = false
}

function handleInputDeviceChange(deviceId: string) {
  voiceStore.updateSettings({ inputDeviceId: deviceId })
}

function handleOutputDeviceChange(deviceId: string) {
  voiceStore.updateSettings({ outputDeviceId: deviceId })
}

function handleInputVolumeChange(event: Event) {
  const target = event.target as HTMLInputElement | null
  voiceStore.updateSettings({ inputVolume: target?.valueAsNumber ?? 0 })
}

function handleOutputVolumeChange(event: Event) {
  const target = event.target as HTMLInputElement | null
  voiceStore.updateSettings({ outputVolume: target?.valueAsNumber ?? 0 })
}

function handleNoiseSuppressionChange(enabled: boolean) {
  voiceStore.updateSettings({ noiseSuppression: enabled })
}

function handleNoiseSuppressionLevelChange(event: Event) {
  const target = event.target as HTMLInputElement | null
  voiceStore.updateSettings({ noiseSuppressionLevel: target?.valueAsNumber ?? 0 })
}

function handleEchoCancellationChange(enabled: boolean) {
  voiceStore.updateSettings({ echoCancellation: enabled })
}

function handleAutoGainControlChange(enabled: boolean) {
  voiceStore.updateSettings({ autoGainControl: enabled })
}

function handleSpatialAudioChange(event: Event) {
  const target = event.target as HTMLInputElement | null
  voiceStore.updateSettings({ spatialAudio: target?.checked ?? false })
}

function handlePushToTalkChange(event: Event) {
  const target = event.target as HTMLInputElement | null
  voiceStore.updateSettings({ pushToTalk: target?.checked ?? false })
}

function handlePushToTalkKeyChange(event: FocusEvent | KeyboardEvent) {
  if ('code' in event) {
    // KeyboardEvent - use event.code
    voiceStore.updateSettings({ pushToTalkKey: event.code })
  } else {
    // FocusEvent - use target.value
    const target = event.target as HTMLInputElement | null
    voiceStore.updateSettings({ pushToTalkKey: target?.value ?? '' })
  }
}

function handleVoiceActivationThresholdChange(event: Event) {
  const target = event.target as HTMLInputElement | null
  voiceStore.updateSettings({ voiceActivationThreshold: target?.valueAsNumber ?? 0 })
}

function handleLogout() {
  authStore.clearAuth()
}

onMounted(() => {
  refreshDevices()
})

onUnmounted(() => {
  stopTestTone()
})
</script>

<template>
  <div class="settings-view">
    <header class="settings-header">
      <h1>Einstellungen</h1>
      <button @click="$router.push('/voice')" class="btn btn-icon" aria-label="Zurück zum Sprachchat">
        <svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
          <path d="M19 12H5M12 19l-7-7 7-7" />
        </svg>
      </button>
    </header>
    
    <main class="settings-main">
      <section class="settings-section">
        <h2>Audio-Geräte</h2>
        
        <div class="setting-group">
          <label for="inputDevice">Eingabegerät (Mikrofon)</label>
          <select
            id="inputDevice"
            v-model="settings.inputDeviceId"
            @change="handleInputDeviceChange(($event.target as HTMLSelectElement).value)"
            class="setting-select"
          >
            <option value="">Standardgerät verwenden</option>
            <option v-for="device in inputDevices" :key="device.deviceId" :value="device.deviceId">
              {{ device.label || `Mikrofon ${device.deviceId.slice(0, 8)}` }}
            </option>
          </select>
          <button @click="refreshDevices" class="btn btn-sm btn-secondary">
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <polyline points="23 4 23 10 17 10" />
              <path d="M20.49 15a9 9 0 1 1-2.12-9.36L23 10" />
            </svg>
            Geräte aktualisieren
          </button>
        </div>
        
        <div class="setting-group">
          <label for="outputDevice">Ausgabegerät (Lautsprecher/Kopfhörer)</label>
          <select
            id="outputDevice"
            v-model="settings.outputDeviceId"
            @change="handleOutputDeviceChange(($event.target as HTMLSelectElement).value)"
            class="setting-select"
          >
            <option value="">Standardgerät verwenden</option>
            <option v-for="device in outputDevices" :key="device.deviceId" :value="device.deviceId">
              {{ device.label || `Lautsprecher ${device.deviceId.slice(0, 8)}` }}
            </option>
          </select>
        </div>
        
        <div class="setting-group">
          <label>
            <input
              type="checkbox"
              v-model="settings.echoCancellation"
              @change="handleEchoCancellationChange(($event.target as HTMLInputElement).checked)"
            />
            Echo-Unterdrückung
          </label>
        </div>
        
        <div class="setting-group">
          <label>
            <input
              type="checkbox"
              v-model="settings.autoGainControl"
              @change="handleAutoGainControlChange(($event.target as HTMLInputElement).checked)"
            />
            Automatische Verstärkungsregelung
          </label>
        </div>
      </section>
      
      <section class="settings-section">
        <h2>Lautstärke</h2>
        
        <div class="setting-group">
          <label>Mikrofon-Lautstärke: {{ Math.round(settings.inputVolume * 100) }}%</label>
          <input
            type="range"
            min="0"
            max="1"
            step="0.01"
            v-model="settings.inputVolume"
            @input="handleInputVolumeChange($event)"
            class="setting-slider"
          />
        </div>

        <div class="setting-group">
          <label>Ausgabe-Lautstärke: {{ Math.round(settings.outputVolume * 100) }}%</label>
          <input
            type="range"
            min="0"
            max="1"
            step="0.01"
            v-model="settings.outputVolume"
            @input="handleOutputVolumeChange($event)"
            class="setting-slider"
          />
        </div>
        
        <div class="setting-group">
          <button @click="playTestTone" class="btn" :class="{ 'btn-primary': testTonePlaying, 'btn-secondary': !testTonePlaying }">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5" />
              <path d="M19.07 4.93a10 10 0 0 1 0 14.14M15.54 8.46a5 5 0 0 1 0 7.07" />
            </svg>
            {{ testTonePlaying ? 'Testton stoppen' : 'Testton abspielen' }}
          </button>
        </div>
      </section>
      
      <section class="settings-section">
        <h2>Rauschunterdrückung (RNNoise)</h2>
        
        <div class="setting-group">
          <label>
            <input
              type="checkbox"
              v-model="settings.noiseSuppression"
              @change="handleNoiseSuppressionChange(($event.target as HTMLInputElement).checked)"
            />
            Rauschunterdrückung aktivieren
          </label>
          <p class="setting-description">
            Verwendet RNNoise (KI-basiert) zur Entfernung von Hintergrundgeräuschen.
          </p>
        </div>
        
        <div class="setting-group" v-show="settings.noiseSuppression">
          <label>Stärke: {{ Math.round(settings.noiseSuppressionLevel * 100) }}%</label>
          <input
            type="range"
            min="0"
            max="1"
            step="0.05"
            v-model="settings.noiseSuppressionLevel"
            @input="handleNoiseSuppressionLevelChange($event)"
            class="setting-slider"
          />
          <p class="setting-description">
            Höhere Werte entfernen mehr Rauschen, können aber Sprache leicht verzerren.
          </p>
        </div>
      </section>
      
      <section class="settings-section">
        <h2>3D-Audio (Räumliches Audio)</h2>
        
        <div class="setting-group">
          <label>
            <input
              type="checkbox"
              v-model="settings.spatialAudio"
              @change="handleSpatialAudioChange($event)"
            />
            Räumliches Audio aktivieren
          </label>
          <p class="setting-description">
            Positioniert Stimmen basierend auf der 3D-Position der Teilnehmer.
          </p>
        </div>
      </section>
      
      <section class="settings-section">
        <h2>Sprech-Erkennung</h2>
        
        <div class="setting-group">
          <label>
            <input
              type="checkbox"
              v-model="settings.pushToTalk"
              @change="handlePushToTalkChange($event)"
            />
            Push-to-Talk (Taste gedrückt halten zum Sprechen)
          </label>
        </div>
        
        <div class="setting-group" v-show="settings.pushToTalk">
          <label>Push-to-Talk Taste:</label>
          <input
            type="text"
            v-model="settings.pushToTalkKey"
            @blur="handlePushToTalkKeyChange($event)"
            class="setting-input"
            readonly
            @keydown.prevent="handlePushToTalkKeyChange($event)"
          />
          <p class="setting-description">Klicke in das Feld und drücke die gewünschte Taste.</p>
        </div>
        
        <div class="setting-group" v-show="!settings.pushToTalk">
          <label>Sprachaktivierungs-Schwelle: {{ settings.voiceActivationThreshold }} dB</label>
          <input
            type="range"
            min="-60"
            max="-20"
            step="1"
            v-model="settings.voiceActivationThreshold"
            @input="handleVoiceActivationThresholdChange($event)"
            class="setting-slider"
          />
          <p class="setting-description">
            Niedrigere Werte = empfindlicher (erkennt leisere Sprache).
          </p>
        </div>
      </section>
      
      <section class="settings-section">
        <h2>Account</h2>
        
        <div class="setting-group">
          <p><strong>Benutzername:</strong> {{ authStore.username }}</p>
          <p><strong>User ID:</strong> {{ authStore.userId }}</p>
        </div>
        
        <div class="setting-group">
          <button @click="handleLogout" class="btn btn-danger">
            <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2">
              <path d="M9 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h4" />
              <polyline points="16 17 21 12 16 7" />
              <line x1="21" y1="12" x2="9" y2="12" />
            </svg>
            Abmelden
          </button>
        </div>
      </section>
    </main>
  </div>
</template>

